using System;using System.IO;using System.Linq;using UnityEditor;using UnityEngine;using UnityEngine.SceneManagement;
[InitializeOnLoad]public static partial class GardenBoundaryPrefabBuilder{
static GardenBoundaryPrefabBuilder(){EditorApplication.update+=Poll;}static void Poll(){if(EditorApplication.isCompiling||EditorApplication.isPlayingOrWillChangePlaymode||!File.Exists("GardenBoundaryPrefab.request"))return;string mode=File.ReadAllText("GardenBoundaryPrefab.request").Trim();File.Delete("GardenBoundaryPrefab.request");try{if(mode=="place")PlaceInTargetScene();else if(mode=="build")Build();else Audit();}catch(Exception e){File.WriteAllText("FinalEnvironmentRoadReview/GardenBoundaryPrefab.txt",e.ToString());Debug.LogException(e);}}
static void Audit(){var sc=SceneManager.GetActiveScene();var roots=sc.GetRootGameObjects();string log="Scene="+sc.path+"\n";foreach(var r in roots.SelectMany(g=>g.GetComponentsInChildren<Renderer>(true)).Where(r=>r.name=="polySurface47"||r.name=="polySurface742"))log+=r.name+" "+r.bounds+"\n";foreach(string p in new[]{"Assets/Scenes/Oasis/3D/Prefeb/Palm.prefab","Assets/Scenes/Oasis/3D/Prefeb/Palm 1.prefab","Assets/Scenes/Oasis/Art/Vegetation/Prefabs/Palms/DatePalm_01_Prefab.prefab","Assets/Scenes/Oasis/SouthBeach/BeachDetails/Existing Curved City Palm.prefab"}){var a=AssetDatabase.LoadAssetAtPath<GameObject>(p);if(!a)continue;var obj=UnityEngine.Object.Instantiate(a);obj.transform.position=Vector3.zero;var rs=obj.GetComponentsInChildren<Renderer>(true);var b=rs[0].bounds;foreach(var r in rs.Skip(1))b.Encapsulate(r.bounds);log+=p+" bounds="+b+" lods="+obj.GetComponentsInChildren<LODGroup>(true).Length+" renderers="+rs.Length+" tris="+string.Join(",",obj.GetComponentsInChildren<MeshFilter>(true).Select(f=>f.sharedMesh?f.sharedMesh.GetIndexCount(0)/3:0))+" mats="+string.Join(";",rs.SelectMany(r=>r.sharedMaterials).Where(m=>m).Distinct().Select(m=>m.name+":"+m.shader.name))+"\n";UnityEngine.Object.DestroyImmediate(obj);}File.WriteAllText("FinalEnvironmentRoadReview/GardenBoundaryAudit.txt",log);}

}



